/* @lc app=leetcode id=3886 lang=kotlin */ class Solution { fun sortableIntegers(nums: IntArray): Int = nums.size.let { n -> (1..n).filter { n % it == 0 }.filter { k -> (0 until n / k).all { j -> (0 until k).count { t -> nums[j * k + t] > nums[j * k + (t + 1) % k] } <= 1 } && (0 until n / k - 1).all { j -> (j * k until (j + 1) * k).maxOf { nums[it] } <= ((j + 1) * k until (j + 2) * k).minOf { nums[it] } } }.sum() } }